use vstd::prelude::*;

verus! {

/// Check if the input vector `v` is "all lowercase":
/// i.e., length is positive and every character is between 'a' and 'z' inclusive.
spec fn check_all_lowercase(v: &Vec<char>) -> bool {
    &&& v.len() > 0
    &&& forall(|i: int| 0 <= i && i < v.len() ==>
            ('a' as u32) <= (v.index(i) as u32) && (v.index(i) as u32) <= ('z' as u32)
        )
}

/// The function takes an input vector of characters and returns a single-character vector,
/// either ['a'] if input is all lowercase, or ['A'] otherwise.
/// Ensures that the output is exactly ['a'] or ['A'] as per the rule.
fn solve(input: Vec<char>) -> Vec<char>
    ensures
        (check_all_lowercase(&input) ==> (result.len() == 1 && result.index(0) == 'a'))
        && (!check_all_lowercase(&input) ==> (result.len() == 1 && result.index(0) == 'A')),
{
    if input.len() > 0 {
        // Use a loop to check all chars are lowercase letters 'a'..'z'
        let mut i = 0;
        while i < input.len()
            invariant
                0 <= i && i <= input.len(),
                // all chars seen so far are lowercase
                forall(|j: int| 0 <= j && j < i as int ==> 
                    ('a' as u32) <= (input.index(j) as u32) && (input.index(j) as u32) <= ('z' as u32)
                ),
            decreases input.len() - i,
        {
            if !(('a' as u32) <= (input.index(i) as u32) && (input.index(i) as u32) <= ('z' as u32)) {
                // Found a character outside 'a'..'z'
                return vec!['A'];
            }
            i = i + 1;
        }
        // All characters checked and are lowercase
        vec!['a']
    } else {
        // length == 0 => not all lowercase
        vec!['A']
    }
}

}
